import {createHash} from 'node:crypto';
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export function syntheticFiles(){
 const panels=[1,2].map(n=>({'画面内容':'合成场景'+n,'景别':'全景','机位角度':'平视','当前场景':'测试庭院','当前天气':'晴','当前时间':'午后','生图提示词':'单格底稿'+n,'服装':{'测试人物':'黑衣'},'台词':[{'说话人':'测试人物','类型':'对白','文本':'测试台词'+n}]}));
 const board={'格式':'分镜 JSON 2.2','作品':'合成制作资料','话':11,'话名':'合成测试','格':panels};
 const pkg={'版本':'屏段文字层 1.1','作品':'合成制作资料','话':11,'出图模式':'空泡','版式':{},'排字':{'参考画布宽':1280,'字号':36},'锚点定义':{'格内左上':{'中心':[.25,.16]}},'屏段':[], '文字':[]};
 for(let n=1;n<=2;n++){const sid='段0'+n,pid='E011-00'+n;pkg['屏段'].push({'段ID':sid,'图片':sid+'.png','场景':'测试庭院','格数':1,'格':[{'格ID':pid,'格号':n,'排':1,'排内':'整排'}],'附图':[{'类型':'设定卡','人物':'测试人物','服装':'黑衣','必须':true},...(n===2?[{'类型':'上一段成图','段ID':'段01','必须':false}]:[])],'提示词':{'空泡':'空泡整段原文 '+sid+'\n不要改写','无泡':'无泡整段原文 '+sid+'\n不要改写'},'底图':n===1?{'方式':'本段出图','图片':'底图.png','提示词':'合成氛围底色','铺满':['段01','段02']}:{'方式':'共用','段ID':'段01','图片':'底图.png'}});pkg['文字'].push({'文字ID':'E011-T00'+n,'格ID':pid,'格号':n,'段ID':sid,'顺序':n,'类型':'对白','说话人':'测试人物','文本':'测试台词'+n,'分行':['测试台词'+n],'渲染':'工具','锚点':'格内左上','泡尾':{'方向':'下'}});}
 pkg['文字'].push({'文字ID':'E011-T003','格ID':'E011-001','段ID':'段01','顺序':3,'类型':'特效字','文本':'砰','渲染':'模型'});
 return [{'relativePath':'分镜JSON/第011话_分镜.json',bytes:Buffer.from(JSON.stringify(board))},{'relativePath':'屏段提示词/第011话/第011话_屏段文字层.json',bytes:Buffer.from(JSON.stringify(pkg))}].map(f=>({...f,sha256:sha(f.bytes)}));
}